import {T} from './art.js';
import {clockwiseDelta,TAU} from './tactile.js';
const clamp=(n,a=0,b=1)=>Math.max(a,Math.min(b,n));
const COLORS=['#e59b85','#79b7d5','#e6cb78'];
export class SpecialRepairs{
 constructor(api){this.api=api;this.gesture=null;this.selected=null;this.def=null;this.motor=0;this.pumpAssist=0;this.lastSound=0;this.pointer=new T.Vector3();
  api.tools.addEventListener('pointerdown',e=>this.down(e));api.hotspots.addEventListener('pointerdown',e=>this.down(e));api.canvas.addEventListener('pointerdown',e=>{if(api.get().job.activeTask?.type==='press')this.start(e,'press');});
  window.addEventListener('pointermove',e=>this.move(e));window.addEventListener('pointerup',e=>this.up(e));window.addEventListener('pointercancel',()=>this.reset());
  api.tools.addEventListener('input',e=>{if(e.target.matches('[data-repair-value]')){this.perform('value',{value:+e.target.value/100});}});
  api.tools.addEventListener('click',e=>{const b=e.target.closest('[data-special-action]');if(!b)return;const {job,audio}=api.get();if(job.phase!=='repair')return;audio.unlock();const action=b.dataset.specialAction;
   if(action==='quarter')this.motor=Math.PI/2;else if(action==='cycle'){if(!this.pumpAssist)this.pumpAssist=.7;}else if(action==='pluck'){const t=job.activeTask,mid=(t.zone[0]+t.zone[1])/2,f=[164.81,220,261.63][Math.min(2,t.count)]*Math.pow(2,(t.value-mid)*1.5);audio.tone(f,.55,'triangle',.055);api.get().machine.fx.stringEnergy=1;this.perform('pluck');if(t.lastPluckGood)api.render();}else this.perform(action);api.save();});
 }
 reset(){if(this.gesture?.element)try{this.gesture.element.releasePointerCapture(this.gesture.id);}catch{}this.gesture=null;this.selected=null;this.motor=0;this.pumpAssist=0;const task=this.api.get().job.activeTask;if(task?.type==='pour')task.value=0;const tools=this.api.get().room?.special;if(tools)for(const [k,m] of Object.entries(tools))if(k!=='root')m.visible=false;}
 position(coords){const {machine,world}=this.api.get(),p=new T.Vector3(...coords);machine.root.localToWorld(p);return world.project(p.x,p.y,p.z);}
 render(){const {job}=this.api.get(),task=job.activeTask;if(!task)return;if(this.def!==task.def){this.reset();this.def=task.def;}const {tools,hotspots}=this.api;const d=task.def;
  if(task.type==='wire')tools.innerHTML=`<div class="special-copy"><b>线头和插孔，要颜色相同。</b><p id="special-hint">从左侧线头拖向右侧插孔；也可先点线头，再点插孔。</p><div class="wire-legend">${d.labels.map((s,i)=>`<span style="--wire:${COLORS[i]}">${s} → ${s}</span>`).join('')}</div></div>`;
  if(task.type==='oil')tools.innerHTML='<div class="tool-icon">♧</div><div class="special-copy"><b>每个转轴，都来一点润滑油。</b><p>按住发光转轴滴油，看到金色油珠就换下一处。</p><small id="special-hint">车轮会从卡顿，慢慢变得顺畅。</small></div>';
  if(task.type==='press')tools.innerHTML='<div class="tool-icon">▥</div><div class="special-copy"><b>拿压轮，把贴片滚压牢。</b><p>直接在补胎片上左右来回拖动，压紧四个角。</p><small id="special-hint">要移动压轮，按住不动不会自动完成。</small></div>';
  if(task.type==='pump')tools.innerHTML=`<div class="pump-tools"><div class="pump-rail" id="pump-rail"><button class="pump-grab" data-pump aria-label="上下拖动打气筒手柄">━━</button><span>↑ 拉起<br>↓ 压下</span></div><div class="pump-copy"><b>拉到顶，压到底。</b><div class="pressure-track"><i class="pressure-zone"></i><i id="pressure-fill"></i></div><p>胎压 <output id="pressure">0</output> / 100 <small>目标 65–85</small></p><div class="special-buttons"><button data-special-action="check">检查胎压</button><button data-special-action="vent">放一点气</button><button data-special-action="cycle" class="assist">辅助压一次</button></div></div></div>`;
  if(task.type==='wind')tools.innerHTML='<div class="screw-tools"><button id="special-wheel" class="turn-wheel" aria-label="顺时针转动发条钥匙"><span class="wheel-face"><i class="wheel-grip"></i><b>↻</b><small id="special-turns">0 / 2 圈</small></span></button><div class="screw-copy"><b>顺时针给机芯上弦。</b><p>看齿轮一起咬合转动。</p><button data-special-action="quarter" class="ratchet">辅助：转 ¼ 圈 ↻</button></div></div>';
  if(task.type==='strings')tools.innerHTML=`<div class="string-tools"><div class="special-copy"><b>第 ${task.count+1} 根弦 · ${['E3','A3','C4'][Math.min(2,task.count)]}</b><p>调弦钮到绿色音准区，再拨弦试听。</p><div class="special-slider"><i style="left:${task.zone[0]*100}%;width:${(task.zone[1]-task.zone[0])*100}%"></i><input type="range" min="0" max="100" value="${task.value*100}" data-repair-value aria-label="吉他弦张力"></div></div><button class="hold-button" data-special-action="pluck"><span>♫</span>拨弦试听</button></div>`;
  if(task.type==='stitch'||task.type==='seal')tools.innerHTML=`<div class="tool-icon">${task.type==='stitch'?'⌁':'▱'}</div><div class="special-copy"><b>${task.type==='stitch'?'穿针引线，留下一道道小针脚。':'沿裂缝点涂，别漏掉转角。'}</b><p>${task.type==='stitch'?'按金色针孔的顺序，拖动针或逐个点击。':'跟着金色标记拖动胶枪，也可以逐个点涂。'}</p><small id="special-hint">下一处：${Math.min(d.points.length,task.count+1)} / ${d.points.length}</small></div>`;
  if(task.type==='pour')tools.innerHTML=`<div class="special-copy"><b>扶稳水壶，让水流落进花盆。</b><p id="pour-advice">把倾角保持在绿色区，小苗会慢慢喝饱。</p><div class="special-slider"><i style="left:35%;width:27%"></i><input type="range" min="0" max="100" value="${task.value*100}" data-repair-value aria-label="浇水壶倾角"></div></div>`;
  hotspots.innerHTML='';const pointButton=(coords,i,label,extra='')=>{const b=document.createElement('button');b.className=`hotspot special-point ${extra}`;b.dataset.specialPoint=i;b.dataset.label=label;b.setAttribute('aria-label',label);b.textContent=['stitch','seal'].includes(task.type)?i+1:'+';hotspots.append(b);};
  if(task.type==='wire'){for(const side of ['start','end'])d[side==='start'?'points':'ends'].forEach((p,i)=>{pointButton(p,i,`${d.labels[i]}${side==='start'?'线头':'插孔'}`,'wire-point');const b=hotspots.lastChild;b.dataset.side=side;b.style.setProperty('--wire',COLORS[i]);b.textContent=d.labels[i];});}
  else if(['stitch','seal','oil'].includes(task.type))d.points.forEach((p,i)=>pointButton(p,i,d.labels[i],task.type==='oil'?'oil-point':'trace-point'));
  else if(task.type==='press'){const b=document.createElement('button');b.className='hotspot patch-touch';b.dataset.press='';b.setAttribute('aria-label','在补胎贴上来回滚压');b.textContent='↔';hotspots.append(b);}
  this.updateUI();this.positionHotspots();
 }
 positionHotspots(){const task=this.api.get().job.activeTask;if(!task)return;for(const b of this.api.hotspots.children){if(!b.matches('.special-point,.patch-touch'))continue;let coords;if(b.hasAttribute('data-press'))coords=[-.84,.92,.25];else coords=task.def[b.dataset.side==='end'?'ends':'points'][+b.dataset.specialPoint];const p=this.position(coords);b.style.left=`${p.x}px`;b.style.top=`${p.y}px`;}}
 updateUI(){const task=this.api.get().job.activeTask;if(!task)return;const {tools,hotspots}=this.api;const out=tools.querySelector('#pressure');if(out)out.textContent=Math.round(task.level*100);const fill=tools.querySelector('#pressure-fill');if(fill)fill.style.width=`${task.level*100}%`;const grab=tools.querySelector('[data-pump]');if(grab)grab.style.top=`${task.value*54}px`;const wheel=tools.querySelector('#special-wheel');if(wheel){wheel.style.setProperty('--turn',`${task.progress*720}deg`);wheel.style.setProperty('--fill',`${task.progress*360}deg`);tools.querySelector('#special-turns').textContent=`${(task.progress*2).toFixed(1)} / 2 圈`;}
  const hint=tools.querySelector('#special-hint');if(hint&&['stitch','seal'].includes(task.type))hint.textContent=`下一处：${Math.min(task.def.points.length,task.count+1)} / ${task.def.points.length}`;if(task.type==='wire'&&hint)hint.textContent=this.selected===null?'从左侧线头拖向右侧插孔；也可先点线头，再点插孔。':`已拿起${task.def.labels[this.selected]}线，放进右侧同色插孔。`;
  const pour=tools.querySelector('#pour-advice');if(pour)pour.textContent=task.value>.62?'太陡了，水洒到外面啦。把壶稍微扶正。':task.value<.35?'轻轻倾斜水壶，绿色区表示刚好的水流。':'水流刚刚好，小苗正在喝水。';
  for(const b of hotspots.children){if(!b.hasAttribute('data-special-point'))continue;const i=+b.dataset.specialPoint,done=task.type==='wire'?task.values[i]>=1:task.type==='oil'?task.values[i]>=1:i<task.count;b.classList.toggle('finished',done);b.classList.toggle('next-point',['stitch','seal'].includes(task.type)&&i===task.count);b.classList.toggle('selected',task.type==='wire'&&b.dataset.side==='start'&&this.selected===i);if(task.type==='oil')b.style.setProperty('--filled',`${task.values[i]*360}deg`);}
 }
 perform(kind,data={}){const c=this.api.get();if(c.paused||c.job.phase!=='repair')return;const result=c.job.action(kind,data);if(result.changed){if(kind==='trace')c.foley.noiseHit(.08,c.job.spec.id==='bear'?950:1600,.025);else if(kind==='connect'||kind==='check')c.foley.seat();else if(kind==='turn'&&Math.floor(c.job.activeTask?.progress*16)!==this.lastWindTick){this.lastWindTick=Math.floor(c.job.activeTask?.progress*16);c.foley.click(.5);}}if(c.job.events.length)this.api.consume();return result;}
 surfacePoint(e){const c=this.api.get(),coords=c.job.activeTask?.def.points?.[0]||[0,0,.6],p=new T.Vector3(...coords);c.machine.root.localToWorld(p);return this.api.toWorld(e,p.z);}
 start(e,kind,data={}){if(this.api.get().paused||this.api.get().job.phase!=='repair'||this.gesture||e.button>0)return;this.api.get().audio.unlock();this.gesture={id:e.pointerId,element:e.currentTarget,kind,last:this.api.local(e),...data};const p=this.surfacePoint(e);if(p)this.pointer.copy(p);try{e.currentTarget.setPointerCapture(e.pointerId);}catch{}e.preventDefault();}
 down(e){const c=this.api.get(),task=c.job.activeTask;if(c.paused||c.job.phase!=='repair')return;const b=e.target.closest('[data-special-point],[data-press],[data-pump],#special-wheel');if(!b)return;const i=+b.dataset.specialPoint;
  if(task.type==='wire'){if(b.dataset.side==='start'){this.selected=i;this.start(e,'wire',{source:i});this.updateUI();}else if(this.selected!==null){this.perform('connect',{source:this.selected,target:i});this.selected=null;this.updateUI();this.api.save();}}
  else if(task.type==='oil')this.start(e,'apply',{index:i});
  else if(task.type==='stitch'||task.type==='seal'){this.start(e,'trace');this.perform('trace',{index:i});this.api.save();}
  else if(task.type==='press')this.start(e,'press');
  else if(task.type==='pump'){const r=document.getElementById('pump-rail').getBoundingClientRect();this.start(e,'pump',{top:r.top+16,height:54});}
  else if(task.type==='wind'){const r=b.getBoundingClientRect(),center={x:r.x+r.width/2,y:r.y+r.height/2};this.start(e,'wind',{center,angle:Math.atan2(e.clientY-center.y,e.clientX-center.x)});}
 }
 nearest(p,coords,radius=33){let closest=-1,best=radius;coords.forEach((v,i)=>{const s=this.position(v),d=Math.hypot(p.x-s.x,p.y-s.y);if(d<best){best=d;closest=i;}});return closest;}
 move(e){const g=this.gesture,c=this.api.get(),task=c.job.activeTask;if(!g||e.pointerId!==g.id||!task)return;const p=this.api.local(e),length=Math.hypot(p.x-g.last.x,p.y-g.last.y);
  if(g.kind==='press'&&length>1){const n=Math.max(1,Math.min(25,Math.ceil(length/5)));for(let k=1;k<=n&&c.job.phase==='repair';k++){const q={x:g.last.x+(p.x-g.last.x)*k/n,y:g.last.y+(p.y-g.last.y)*k/n};task.def.points.forEach((v,i)=>{const s=this.position(v);if(Math.hypot(q.x-s.x,q.y-s.y)<38)this.perform('apply',{index:i,amount:.09});});}c.foley.stroke(0,.5);}
  if(g.kind==='trace'){const n=Math.max(1,Math.min(40,Math.ceil(length/5)));for(let k=1;k<=n;k++){const q={x:g.last.x+(p.x-g.last.x)*k/n,y:g.last.y+(p.y-g.last.y)*k/n},i=this.nearest(q,task.def.points,29);if(i===task.count)this.perform('trace',{index:i});}}
  if(g.kind==='pump')this.perform('value',{value:clamp((e.clientY-g.top)/g.height)});
  if(g.kind==='wind'){const angle=Math.atan2(e.clientY-g.center.y,e.clientX-g.center.x);if(Math.hypot(e.clientX-g.center.x,e.clientY-g.center.y)>15)this.perform('turn',{angle:clockwiseDelta(g.angle,angle)});g.angle=angle;}
  const worldPoint=this.surfacePoint(e);if(worldPoint)this.pointer.copy(worldPoint);if(this.gesture)this.gesture.last=p;
 }
 up(e){const g=this.gesture,c=this.api.get(),task=c.job.activeTask;if(!g||e.pointerId!==g.id)return;if(g.kind==='wire'&&task?.type==='wire'){const target=this.nearest(this.api.local(e),task.def.ends,38);if(target>=0){this.perform('connect',{source:g.source,target});this.selected=null;}}if(g.element)try{g.element.releasePointerCapture(g.id);}catch{}this.gesture=null;this.updateUI();this.api.save();}
 update(dt,time){const c=this.api.get(),task=c.job.activeTask,toolset=c.room?.special;if(!toolset)return;for(const [k,m] of Object.entries(toolset))if(k!=='root')m.visible=false;if(c.paused||c.job.phase!=='repair'||!task)return;
  if(this.motor>0&&task.type==='wind'){const a=Math.min(this.motor,dt*5);this.motor-=a;this.perform('turn',{angle:a});if(!this.motor)this.api.save();}
  if(this.pumpAssist>0&&task.type==='pump'){this.pumpAssist=Math.max(0,this.pumpAssist-dt);const t=1-this.pumpAssist/.7;this.perform('value',{value:(1-Math.cos(t*TAU))*.5});if(!this.pumpAssist)this.api.save();}
  const g=this.gesture;if(g?.kind==='apply'&&task.type==='oil'){this.perform('apply',{index:g.index,amount:dt*1.5});if(time-this.lastSound>.2){c.foley.click(.2);this.lastSound=time;}}
  const tool=toolset[task.type];if(tool&&g){tool.visible=true;const point=g.kind==='apply'?new T.Vector3(...task.def.points[g.index]).applyMatrix4(c.machine.root.matrixWorld):this.pointer;tool.position.copy(point);tool.position.z+=task.type==='press'?.13:task.type==='stitch'?.05:.25;tool.rotation.z=Math.sin(time*8)*.04;}
  if(task.type==='pour'&&task.value>.12&&time-this.lastSound>.1){c.foley.noiseHit(.13,1300,.025);this.lastSound=time;}this.updateUI();this.positionHotspots();
 }
}
